package com.fitnutri.backend.summary;

import com.fitnutri.backend.common.*;
import com.fitnutri.backend.profile.*;
import com.fitnutri.backend.summary.SummaryModels.*;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class SummaryServiceTest {
    private final SummaryRepository repository=mock(SummaryRepository.class);private final UserProfileRepository profiles=mock(UserProfileRepository.class);private final WeightEntryRepository weights=mock(WeightEntryRepository.class);
    private final SummaryService service=new SummaryService(repository,profiles,weights,new RecordDatePolicy(Clock.fixed(Instant.parse("2026-10-16T13:30:00Z"),ZoneOffset.UTC),new ZoneResolver("Australia/Sydney")),new RuleSummaryService());
    private final LocalDate from=LocalDate.of(2020,1,1),to=from.plusDays(2),previous=from.minusDays(3);
    private MetricAggregate metric(long count,long known,String sum,long legacy){return MetricAggregate.of(count,known,sum==null?null:new BigDecimal(sum),legacy);}
    private void arrange(){
        when(repository.foodDays(1L,previous,to)).thenReturn(List.of(new SummaryRepository.FoodDay(from,2,metric(2,1,"100",1),metric(2,0,null,0),metric(2,2,"5",0),metric(2,2,"10",0)),new SummaryRepository.FoodDay(from.plusDays(1),1,metric(1,0,null,0),metric(1,1,"12",0),metric(1,1,"0",0),metric(1,0,null,0))));
        when(repository.exerciseDays(1L,previous,to)).thenReturn(List.of(new SummaryRepository.ExerciseDay(from,1,metric(1,0,null,0),new BigDecimal("10.50")),new SummaryRepository.ExerciseDay(from.plusDays(1),1,metric(1,1,"0",0),new BigDecimal("20.00"))));
    }
    @Test void hundredNullZeroAndPartialMetricsUseEachOwnKnownDayDenominator(){arrange();var result=service.period(1L,from,to,"Australia/Sydney");assertEquals(3,result.calendarDayCount());assertEquals(new BigDecimal("100"),result.totals().intake().knownSum());assertEquals(3,result.totals().foodCount());assertEquals(1,result.totals().intake().knownValueCount());assertEquals(2,result.totals().intake().missingValueCount());assertTrue(result.totals().intake().partial());assertEquals(1,result.totals().intake().legacyValueCount());assertEquals(new BigDecimal("100.000"),result.averages().intake().value());assertEquals(1,result.averages().intake().knownDayCount());assertEquals(new BigDecimal("12.000"),result.averages().protein().value());assertEquals(1,result.averages().protein().knownDayCount());assertEquals(new BigDecimal("2.500"),result.averages().fat().value());assertEquals(2,result.averages().fat().knownDayCount());assertEquals(new BigDecimal("0.000"),result.averages().expenditure().value());assertEquals(1,result.averages().expenditure().knownDayCount());assertEquals(new BigDecimal("30.50"),result.totals().activityMinutes());assertEquals(new BigDecimal("15.250"),result.averages().activityMinutes().value());assertEquals(2,result.averages().activityMinutes().knownDayCount());}
    @Test void allMissingDayAndAbsentDayStayDistinctAndNoChartZeroIsInvented(){arrange();var result=service.period(1L,from,to,null);var missing=result.days().get(1).intake();var absent=result.days().get(2).intake();assertTrue(missing.hasData());assertEquals(1,missing.missingValueCount());assertNull(missing.knownSum());assertFalse(absent.hasData());assertEquals(0,absent.recordCount());assertNull(absent.knownSum());assertNull(result.days().get(2).activityMinutes());assertNull(result.goalComparison());}
    @Test void explicitCurrentTargetOnlyComparesKnownIntakeDaysWithoutExerciseOffset(){arrange();when(profiles.findDailyTargetKjByUserId(1L)).thenReturn(Optional.of(new BigDecimal("8400.000")));var goal=service.period(1L,from,to,null).goalComparison();assertEquals(1,goal.comparedDays());assertEquals(new BigDecimal("100"),goal.knownIntakeKj());assertEquals(new BigDecimal("8400.000"),goal.targetForComparedDaysKj());verify(profiles,never()).findById(any());}
    @Test void emptyRangeIsValidButReadFailurePropagatesInsteadOfFakeEmptySuccess(){var result=service.period(1L,from,to,null);assertFalse(result.totals().intake().hasData());assertNull(result.averages().intake().value());assertEquals(0,result.averages().intake().knownDayCount());assertTrue(result.facts().stream().anyMatch(f->f.code().equals("RECORDED_COVERAGE")));when(repository.foodDays(1L,previous,to)).thenThrow(new IllegalStateException("synthetic persistence outage"));assertThrows(IllegalStateException.class,()->service.period(1L,from,to,null));}
    @Test void invalidBoundsAndAmbiguousDaysShortcutFailBeforeDatabaseCalls(){assertThrows(BusinessException.class,()->service.trends(1L,from,to,7,null));assertThrows(BusinessException.class,()->service.trends(1L,from,null,null,null));assertThrows(BusinessException.class,()->service.trends(1L,null,null,367,null));assertThrows(BusinessException.class,()->service.period(1L,to,from,null));verifyNoInteractions(repository,profiles,weights);}
    @Test void todayAndExplicitDailyShareClockZoneAndSameAggregation(){var today=service.today(1L,"Australia/Sydney");assertEquals(LocalDate.of(2026,10,17),today.day().recordDate());assertEquals(today,service.daily(1L,LocalDate.of(2026,10,17),"Australia/Sydney"));assertEquals(LocalDate.of(2026,10,16),service.today(1L,"UTC").day().recordDate());}
    @Test void previousSameLengthComparisonUsesKnownDataAndReportsInsufficiencyWhenAbsent(){arrange();var result=service.period(1L,from,to,null);assertTrue(result.facts().stream().anyMatch(f->f.code().equals("INSUFFICIENT_COMPARISON_DATA")));when(repository.foodDays(1L,previous,to)).thenReturn(List.of(new SummaryRepository.FoodDay(previous,1,metric(1,1,"200",0),metric(1,0,null,0),metric(1,0,null,0),metric(1,0,null,0)),new SummaryRepository.FoodDay(from,1,metric(1,1,"100",0),metric(1,0,null,0),metric(1,0,null,0),metric(1,0,null,0))));var compared=service.period(1L,from,to,null);var change=compared.facts().stream().filter(f->f.code().equals("INTAKE_AVERAGE_CHANGE")).findFirst().orElseThrow();assertEquals(new BigDecimal("-100.000"),change.values().get("difference"));assertEquals(1,change.values().get("currentKnownDayCount"));assertEquals(1,change.values().get("previousKnownDayCount"));}
}
